import math
from collections import defaultdict

# --------------------------------------------------------------------------- #
# Helper functions – no document I/O, only pure math
# --------------------------------------------------------------------------- #

def _parse_state_input(inp):
    """Convert a state input record into a dictionary suitable for simulation."""
    fields = inp["fields"]
    return {
        "frame": fields["frame"],
        "x": float(fields["x"]),
        "y": float(fields["y"]),
        "vx": float(fields["vx"]),
        "vy": float(fields["vy"]),
    }

def _advance_state_to(state, target_frame):
    """Advance a constant‑velocity state to the target frame."""
    f_start = state["frame"]
    dt_frames = target_frame - f_start
    dt_sec = dt_frames / 25.0
    new_state = state.copy()
    new_state["x"] += state["vx"] * dt_sec
    new_state["y"] += state["vy"] * dt_sec
    new_state["frame"] = target_frame
    return new_state

def _distance(o1, o2):
    return math.hypot(o1["x"] - o2["x"], o1["y"] - o2["y"])

def _elastic_collision(o1, o2):
    """Perfectly elastic exchange (equal masses, no friction)."""
    dx = o1["x"] - o2["x"]
    dy = o1["y"] - o2["y"]
    dist_sq = dx * dx + dy * dy
    if dist_sq == 0:
        return
    dvx = o1["vx"] - o2["vx"]
    dvy = o1["vy"] - o2["vy"]
    dot = dvx * dx + dvy * dy
    if dot >= 0:
        return
    factor = dot / dist_sq
    o1["vx"] -= factor * dx
    o1["vy"] -= factor * dy
    o2["vx"] += factor * dx
    o2["vy"] += factor * dy

# --------------------------------------------------------------------------- #
# Main simulation routine
# --------------------------------------------------------------------------- #

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward model for a CLEVRER video.

    The model is deterministic and uses only the supplied `inputs`.  It runs
    from `start` to `horizon` (in frame numbers).  The routine emulates
    constant‑velocity motion, updates states when a state input appears,
    detects collisions when the euclidean distance becomes ≤ 0.5, and
    applies a perfectly elastic collision between equal‑mass objects.
    """
    # Gather all entities that appear in the inputs
    entities = set()
    for inp in inputs:
        entities.update(inp["entities"])
    if not entities:
        return []

    # Resolve simulation bounds
    if start is None:
        start = min(inp["time"] for inp in inputs)
    start_frame = int(round(start))

    if horizon is None:
        rec_end = recorded_end(doc, scope)
        horizon_frame = rec_end if rec_end is not None else (start_frame + 2000)
    else:
        horizon_frame = int(round(horizon))

    # Build per‑object state timelines from inputs
    state_timeline = defaultdict(list)      # obj -> list of (frame, state dict)
    for inp in inputs:
        if inp["kind"] == "state":
            obj = inp["entities"][0]
            state = _parse_state_input(inp)
            state_timeline[obj].append((state["frame"], state))
    for obj in state_timeline:
        state_timeline[obj].sort(key=lambda x: x[0])  # sort by frame

    # Initial state at start_frame – take the latest state <= start_frame
    current_state = {}
    for obj in entities:
        # find latest state before or at start_frame
        latest = None
        for frame, state in state_timeline.get(obj, []):
            if frame <= start_frame:
                if latest is None or frame > latest[0]:
                    latest = (frame, state)
        if latest:
            current_state[obj] = latest[1].copy()
            current_state[obj]["frame"] = start_frame  # normalize frame
        else:
            # if no prior state, use the earliest after start (backward‑propagate)
            future = None
            for frame, state in state_timeline.get(obj, []):
                if frame > start_frame:
                    if future is None or frame < future[0]:
                        future = (frame, state)
            if future:
                # advance it back to start_frame
                st = _advance_state_to(future[1], start_frame)
                current_state[obj] = st
            else:
                # completely unknown – assume zero motion
                current_state[obj] = {"frame": start_frame, "x": 0.0, "y": 0.0, "vx": 0.0, "vy": 0.0}

    COLLISION_THRESH = 0.5   # empirical from data
    outcomes = []
    entities_list = list(entities)

    # Simulation loop
    for cur_f in range(start_frame, horizon_frame + 1):
        # 1. Apply any state updates that occur at this frame
        for obj in entities_list:
            for frame, state in state_timeline.get(obj, []):
                if frame == cur_f:
                    # Directly set state (no interpolation)
                    current_state[obj] = state.copy()
                    current_state[obj]["frame"] = cur_f
                    break

        if cur_f == start_frame:
            # already at start – skip movement this step
            pass
        else:
            # 2. Move all objects forward by one frame
            for obj in entities_list:
                st = current_state[obj]
                st["x"] += st["vx"] / 25.0
                st["y"] += st["vy"] / 25.0
                st["frame"] = cur_f

        # 3. Detect collisions after movement
        reported_pairs = set()
        for i in range(len(entities_list)):
            for j in range(i + 1, len(entities_list)):
                a, b = entities_list[i], entities_list[j]
                if _distance(current_state[a], current_state[b]) <= COLLISION_THRESH:
                    pair = tuple(sorted((a, b)))
                    if pair in reported_pairs:
                        continue
                    reported_pairs.add(pair)
                    outcomes.append({
                        "time": cur_f,
                        "kind": "collision",
                        "entities": list(pair),
                        "value": None,
                        "src": [],
                    })
                    _elastic_collision(current_state[a], current_state[b])

    # Filter and sort outcomes that occur after the requested start
    outcomes = [o for o in outcomes if o["time"] >= start_frame]
    outcomes.sort(key=lambda o: o["time"])
    return outcomes

