# collision distance threshold per document
def _collision_threshold(doc):
    """Compute a collision threshold from all recorded collision records."""
    collision_distances = []
    for node in doc['nodes']:
        title = node['title']
        if not title.startswith('Video '):
            continue
        scope = title
        # reuse safe outcomes to avoid missing nodes
        for out in outcomes(doc, scope):
            if out.get('kind') != 'collision':
                continue
            t = out.get('time')
            ents = out.get('entities', [])
            if len(ents) != 2:
                continue
            motion_node = node_by_title(doc, f'{scope}: Motion log')
            if motion_node is None or motion_node['kind'] != 'table':
                continue
            pos = []
            for _, row in table_rows(motion_node):
                try:
                    f = int(row['frame'])
                except Exception:
                    continue
                if f != t:
                    continue
                obj_num = re.match(r'(\d+)', row['object'])
                if not obj_num:
                    continue
                ent = f"Object {obj_num.group(1)}"
                if ent in ents:
                    pos.append((float(row['x']), float(row['y'])))
            if len(pos) == 2:
                d = math.hypot(pos[0][0]-pos[1][0], pos[0][1]-pos[1][1])
                collision_distances.append(d)
    if collision_distances:
        return min(collision_distances) * 1.4
    else:
        return 0.02  # fallback safety margin

def simulate(doc, scope, inputs, params, start=None, horizon=None):
    """
    Forward‑model the CLEVRER video process.
    """
    recorded_end = recorded_end(doc, scope)
    horizon = horizon if horizon is not None else recorded_end
    if horizon is None:
        horizon = max((inp['time'] for inp in inputs), default=0)

    start = start if start is not None else 0

    presence = set()
    state_inputs = defaultdict(dict)   # ent -> time -> fields
    for inp in inputs:
        ent = inp['entities'][0]
        presence.add(ent)
        if inp['kind'] == 'state':
            state_inputs[ent][inp['time']] = inp['fields']

    # initialise state at start
    state = {}
    for ent in presence:
        times = [t for t in state_inputs[ent] if t <= start]
        if times:
            t0 = max(times)
            f = state_inputs[ent][t0]
            state[ent] = {
                'frame': t0,
                'x': float(f['x']),
                'y': float(f['y']),
                'vx': float(f['vx']),
                'vy': float(f['vy']),
                'speed': float(f['speed']),
            }
        else:
            state[ent] = {'frame': start, 'x': 0.0, 'y': 0.0,
                          'vx': 0.0, 'vy': 0.0, 'speed': 0.0}

    thresh = _collision_threshold(doc)
    outcomes = []
    collisions_done = set()   # (frame, e1, e2)

    def _swap_vel(e1, e2):
        v1x, v1y = state[e1]['vx'], state[e1]['vy']
        v2x, v2y = state[e2]['vx'], state[e2]['vy']
        state[e1]['vx'], state[e1]['vy'] = v2x, v2y
        state[e2]['vx'], state[e2]['vy'] = v1x, v1y

    for t in range(start + 1, int(horizon) + 1):
        # override with explicit state input
        for ent in presence:
            if t in state_inputs[ent]:
                f = state_inputs[ent][t]
                state[ent].update({
                    'frame': t,
                    'x': float(f['x']),
                    'y': float(f['y']),
                    'vx': float(f['vx']),
                    'vy': float(f['vy']),
                    'speed': float(f['speed']),
                })
        # detect collisions
        ents = sorted(presence)
        for i in range(len(ents)):
            for j in range(i+1, len(ents)):
                e1, e2 = ents[i], ents[j]
                dx = state[e1]['x'] - state[e2]['x']
                dy = state[e1]['y'] - state[e2]['y']
                dist = math.hypot(dx, dy)
                if dist <= thresh:
                    key = (t, e1, e2)
                    if key in collisions_done:
                        continue
                    collisions_done.add(key)
                    outcomes.append({
                        'time': t,
                        'kind': 'collision',
                        'entities': [e1, e2],
                        'value': None,
                        'src': [['simulated', str(t)]]
                    })
                    _swap_vel(e1, e2)
        # advance all positions
        for ent in presence:
            vx, vy = state[ent]['vx'], state[ent]['vy']
            sp = math.hypot(vx, vy)
            if sp < 0.1:
                vx, vy = 0.0, 0.0
                sp = 0.0
            state[ent]['vx'], state[ent]['vy'] = vx, vy
            state[ent]['speed'] = sp
            state[ent]['x'] += vx
            state[ent]['y'] += vy
            state[ent]['frame'] = t

    return [o for o in outcomes if o['time'] > start]

